public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                count++;
                dfs(grid, i, j);
            }
        }
    }
    return count;
}

private static void dfs(char[][] grid, int x, int y) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[x].length || grid[x][y] != '@') {
        return;
    }
    grid[x][y] = '0'; // Mark as visited
    dfs(grid, x + 1, y);
    dfs(grid, x - 1, y);
    dfs(grid, x, y + 1);
    dfs(grid, x, y - 1);
}
