    if (num == 0) {
        return 0;
    }
    int count = 0;
    int power = 1;
    while (num > 0) {
        int digit = num % 10;
        if (digit == 1) {
            count += (num + 1) / power - power / 10;
        }
        num /= 10;
        power *= 10;
    }
    return count;
